type storageIdentity struct {
    FunctionName string // final storage key — site-suffixed when diverted
    ExistingID, ExistingHTML, ExistingSchema string
    ExistingJS sql.NullString
    IsRegeneration bool
    Diverted bool
    DivertedFromID, DivertedFromFunc string
    ForeignDomains []string
    DivertBlocked string
}

func resolveStorageIdentity(ctx context.Context, db *sql.DB, functionName, requesterSiteID, requesterDomain string, logger *zap.Logger) (storageIdentity, error) {
    ident := storageIdentity{FunctionName: functionName}
    found, err := lookupBaseComponent(ctx, db, functionName, &ident) // the store's historical query, moved verbatim (ORDER BY is_active DESC, updated_at DESC LIMIT 1)
    if err != nil { return ident, err }
    if !found { return ident, nil }
    if requesterSiteID == "" { ident.IsRegeneration = true; return ident, nil } // legacy: direct invocation
    foreignIDs, foreignDoms, err := foreignDependents(ctx, db, ident.ExistingID, requesterSiteID)
    if err != nil { ident.IsRegeneration = true; return ident, nil } // unreadable census fails towards legacy, never towards an ungrounded diversion
    if len(foreignIDs) == 0 { ident.IsRegeneration = true; return ident, nil }
    domain := requesterDomain
    if domain == "" { _ = db.QueryRowContext(ctx, `SELECT domain FROM sites WHERE id = $1::uuid`, requesterSiteID).Scan(&domain) }
    if domain == "" { ident.IsRegeneration = true; ident.DivertBlocked = "..."; return ident, nil }
    suffixed := functionName + "-" + domainSlug(domain)
    div := storageIdentity{FunctionName: suffixed, Diverted: true, DivertedFromID: ident.ExistingID, DivertedFromFunc: functionName, ForeignDomains: foreignDoms}
    foundScoped, err := lookupBaseComponent(ctx, db, suffixed, &div)
    if err != nil { return div, err }
    if !foundScoped { return div, nil } // creation under the scoped name
    foreign2, foreignDoms2, err := foreignDependents(ctx, db, div.ExistingID, requesterSiteID)
    if err != nil || len(foreign2) == 0 { div.IsRegeneration = true; return div, nil } // own earlier diverted row
    return div, fmt.Errorf("cannot store component %q: the base name is depended on by other sites (%s) and the site-scoped name %q is too (%s) — refusing to overwrite either", functionName, strings.Join(foreignDoms, ", "), suffixed, strings.Join(foreignDoms2, ", "))
}

func foreignDependents(...) {
    rows, err := db.QueryContext(ctx, `
        SELECT DISTINCT s.id::text, s.domain
        FROM ( SELECT p.site_id FROM page_components pc JOIN pages p ON p.id = pc.page_id WHERE pc.component_id = $1::uuid
               UNION SELECT sc.site_id FROM site_components sc WHERE sc.component_id = $1::uuid ) dep
        JOIN sites s ON s.id = dep.site_id
        WHERE s.id::text <> $2`, componentID, requesterSiteID)
    ...
}

